import{at as e,it as t,n,vt as r}from"./chunks/framework.CsjHfu6k.js";import"./chunks/assets.CAF1-15Q.js";var i=JSON.parse(`{"title":"OTA 升级指南","description":"","frontmatter":{},"headers":[],"relativePath":"ota.md","filePath":"ota.md","lastUpdated":1792939073000}`),a={name:`ota.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ota-升级指南" tabindex="-1">OTA 升级指南 <a class="header-anchor" href="#ota-升级指南" aria-label="Permalink to “OTA 升级指南”">​</a></h1><p>Magisk 默认不会修改只读分区，这使得应用官方 OTA 要简单得多。<strong>仅支持在具有 A/B 分区（无缝系统更新）的设备上使用 OTA 更新。</strong> 在 A/B 设备上，系统运行期间 OTA 会被安装到非活动插槽，从而允许 Magisk app 将 Magisk 安装到更新后的分区，并在更新后保留 root。本文档中的具体流程仅在 Pixel 设备上测试过，因为其他设备的步骤可能有所不同。</p><p><strong>注意：为了应用 OTA，您必须确保自己没有以任何方式修改只读分区（如 <code>/system</code> 或 <code>/vendor</code> ）。即使将分区重新挂载到 rw 也会篡改块验证</strong></p><h2 id="必要条件" tabindex="-1">必要条件 <a class="header-anchor" href="#必要条件" aria-label="Permalink to “必要条件”">​</a></h2><ul><li>请在开发人员选项中禁用<em>自动系统更新</em>，这样在未经您确认的情况下，它不会安装 OTA。</li></ul><p align="center"><img src="/MagiskChineseDocument/images/disable_auto_ota.png" width="250"></p><ul><li>当 OTA 可用时，首先转到（Magisk app → 卸载 → 恢复映像），<strong>不要重新启动，否则将卸载 Magisk。</strong> 这将使 Magisk 修改的分区从安装时的生成备份恢复到官方，以便通过 OTA 前的块验证。<strong>注意：</strong> 对于 Pixel 设备和 Googlebook，不需要恢复启动映像，因为只要有任何分区被修改，Google 的服务器就会自动提供完整 OTA。</li></ul><p align="center"><img src="/MagiskChineseDocument/images/restore_img.png" width="300"></p><h2 id="安装-ota" tabindex="-1">安装 OTA <a class="header-anchor" href="#安装-ota" aria-label="Permalink to “安装 OTA”">​</a></h2><ol><li>按正常方式安装 OTA（设置 → 系统 → 系统更新），并等待安装完全完成（包括“正在安装系统更新”和“正在优化您的设备”）。<strong>暂时不要按“立即重新启动”或“重新启动”按钮！</strong></li><li>转到 Magisk app，选择（<strong>安装 → 安装到非活动插槽（OTA 后）</strong>）将 Magisk 安装到更新后的插槽。</li></ol><p align="center"><img src="/MagiskChineseDocument/images/ota_done.png" width="250"> <img src="/MagiskChineseDocument/images/install_inactive_slot.png" width="250"></p><ol start="3"><li>Magisk 安装完成后，回到系统的 OTA 更新界面，按<strong>立即重新启动</strong>，从那里重新启动进入更新后的插槽。</li></ol><p align="center"><img src="/MagiskChineseDocument/images/install_done.png" width="250"> <img src="/MagiskChineseDocument/images/ota_reboot.png" width="250"></p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to “参考链接”">​</a></h2><ul><li><a href="https://topjohnwu.github.io/Magisk/ota.html" target="_blank" rel="noreferrer">Magisk OTA Upgrade Guides</a>（官方）</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};